using LittleLeo.Variables;
using NaughtyAttributes;
using TMPro;
using UnityEngine;
using UnityEngine.UI;

namespace Astrea;

public class FeedbackInstance : MonoBehaviour
{
	[Header("Movement")]
	[SerializeField]
	protected AnimationCurve movementCurve;

	[SerializeField]
	protected float movementDuration;

	[SerializeField]
	private float movementAmount;

	[SerializeField]
	protected AnimationCurve fadeCurve;

	[SerializeField]
	private float delayToFade;

	[SerializeField]
	protected float fadeDuration;

	[SerializeField]
	private float delayToStore;

	[SerializeField]
	private float startingPositionHeightAdjustment;

	[Header("Components")]
	[SerializeField]
	protected TransformReference feedbackCanvasTransformReference;

	[SerializeField]
	protected TextMeshProUGUI valueText;

	[SerializeField]
	[HideIf("disableIconImage")]
	protected Image iconImage;

	[SerializeField]
	[HideIf("disableIconImage")]
	protected Image shadowImage;

	[Header("Disable Sprite")]
	[SerializeField]
	private bool disableIconImage;

	protected void PlayFeedback(Vector3 unitPosition)
	{
		valueText.SetAlpha(1f);
		if (!disableIconImage)
		{
			iconImage.SetAlpha(1f);
			shadowImage.SetAlpha(1f);
		}
		base.transform.SetParent(feedbackCanvasTransformReference.value);
		base.transform.position = unitPosition.ZeroZ();
		base.transform.localScale = Vector3.one;
		Vector3 startPosition = base.transform.position + Vector3.up * startingPositionHeightAdjustment;
		Vector3 targetPosition = startPosition + Vector3.up * movementAmount;
		StartCoroutine(CoroutineUtility.CurveRoutine(movementDuration, movementCurve, delegate(float t, float v)
		{
			base.transform.position = Vector3.LerpUnclamped(startPosition, targetPosition, v);
		}));
		InvokeAlternatives.Invoke(this, delayToFade, delegate
		{
			FadeSprites();
		});
		InvokeAlternatives.Invoke(this, delayToStore, delegate
		{
			ReferenceSingleton<PoolHandler>.Instance.StoreObject(base.gameObject);
		});
	}

	protected virtual void FadeSprites()
	{
		StartCoroutine(valueText.FadeSprite(0f, fadeDuration, fadeCurve));
		if (!disableIconImage)
		{
			StartCoroutine(iconImage.FadeSprite(0f, fadeDuration, fadeCurve));
			StartCoroutine(shadowImage.FadeSprite(0f, fadeDuration, fadeCurve));
		}
	}
}
